e":{"stt_lang":"ar-JO","tts_lang":"ar-SA","rate":1},"rubric_labels":{"alliance":"التحالف العلاجي والتعاطف","assessment":"التقييم السريري والاستكشاف","interventions":"تدخلات مناسبة","safety":"التعامل مع السلامة والمخاطر","structure":"بنية الجلسة واستخدام الوقت"},"clinical_review":{"status":"approved","reviewer":"Clinical Director — Wave 1 library expansion","notes":"Wave-1 authored SP for ADHD"},"is_active":true,"case_file":{"history_localization":{"substance_and_medication_context":"None prescribed. Caffeine 3–5 coffees/day. Declined friend''s Adderall so far.","present_illness_local":"Software support engineer. Second written warning for missed tickets and late standups. Partner frustrated by chores. Always ''smart but messy''. Never evaluated as child — quiet daydreamer, not disruptive."},"therapy_behaviour":{"opening_line_of_session_one":"بضيّع شغلي. ما بظنّني غبي. بس بحسّ حالي غبي.","the_sentence_that_signals_real_contact":"دفتر ثالث ابتدائي مكتوب عليه: عمر بنجح لو ظل على هالكوكب."}}}}'::jsonb,
