WHERE slug IN ('ocd', 'eating-disorders', 'social-anxiety', 'ptsd', 'schizophrenia', 'bpd', 'alcohol-use-disorder', 'adult-adhd', 'bipolar-mania', 'mdd-recurrent-moderate');
